var n=`0739-tibs`;var t=`world-0739`;var o=`ET`;var s=`eastern-africa`;var a=4;var r=43;var g={en:`Tibs`,ua:`Тібс`};var d={en:`Tibs is a Ethiopia classic prepared with beef sirloin, ginger root, garlic, yellow onion. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Тібс, страва кухні країни Ефіопія зі складниками: яловичий сирлойн, корінь імбиру, часник, жовта цибуля. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 20 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 20 хвилин.`,t:[`marinating`],m:20,i:[[`beef-sirloin`,680,`g`],[`ginger-root`,15,`g`],[`garlic`,4,`clove`],[`ground-cumin`,5,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,180,`g`],[`green-bell-pepper`,230,`g`],[`niter-kibbeh`,50,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 9 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 9 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:9,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`injera`,4,`pcs`],[`parsley`,16,`g`]]}];var u={slug:n,id:t,country:`ET`,region:s,servings:4,minutes:43,title:g,text:d,steps:l};export{o as country,u as default,t as id,r as minutes,s as region,a as servings,n as slug,l as steps,d as text,g as title};